/** Relative URL for a coin logo in the public folder, or null when unknown. */
export function logoUrlFor(symbol: string): string | null {
  const base = baseSymbolOf(symbol);
  const ext = CRYPTO_LOGO_EXT[base];
  return ext ? `logos/${base}.${ext}` : null;
}
